+    let outside = [(43.0, 30.0), (43.0, 34.0), (43.0, 37.0), (43.0, 40.0), (42.6, 41.5), (41.5, 42.6), (40.0, 43.0), (37.0, 43.0), (33.0, 43.0)];
+    let inside = [(37.0, 28.0), (37.0, 32.0), (37.0, 35.0), (37.0, 37.0), (35.0, 37.0), (32.0, 37.0), (28.0, 37.0)];
+    for count in [1, 2] {
